const rows = $input.all().map(i => i.json);
const posts = [];
const postMeta = [];
for (const r of rows) {
  const url = 'https://www.linkedin.com/feed/update/urn:li:activity:' + r.activity_id + '/';
  posts.push(url);
  postMeta.push({ activity_id: r.activity_id, url: url, posted_at: r.posted_at, text: (r.text || '').slice(0, 60) });
}
return [{ json: { posts: posts, postMeta: postMeta, postCount: posts.length } }];

// ===== Roster + headcount come from Supabase (public.linkedin_roster_config),
// editable from the SOV dashboard. The baked-in list below is only a fallback
// so the metric never breaks if the config fetch returns nothing. =====
const FALLBACK_ROSTER = ["Omri Green","Nadav Erez","Yiftach Keshet","Yuval Carmel","Benny Porat","Guilad Regev","Ron Kormanek","Alona Liechtenstein","Justin Woody","Ben Ofer","Charly Setbon","Ofir Tal-Friedman","Yasmin Hefer","Liad Shachoach","Chen Fradkin","Alon Danoch","Matan Coriat","Daniel Shalev","Dustin Rabin","Nadav Misgav","Ariel Zinman","Noa Milshtein","Omer Movshovits","Danielle Hersonsky Sarid","Miki Chernyak","Dotan Reis","Yaniv Wolfus","Elan Smyla","Maayan Arbely","Tanya Gershnov","Danny Nia","Lior Krupnik","Omer Kaplan","Akiva Adler","Noam Bar Uryan","Nadav Barak","Peleg Dvir","Ittay Toledo"];;
let ROSTER = FALLBACK_ROSTER;
let HEADCOUNT = FALLBACK_ROSTER.length;
try {
  const cfg = $('Get roster config (Supabase)').first().json;
  if (cfg) {
    if (Array.isArray(cfg.roster) && cfg.roster.length) ROSTER = cfg.roster;
    const hc = Number(cfg.headcount);
    HEADCOUNT = (Number.isFinite(hc) && hc > 0) ? hc : ROSTER.length;
  }
} catch (e) { /* keep fallback */ }
// ===================================================

function normName(s) {
  return String(s == null ? '' : s)
    .normalize('NFKC')
    .replace(/[​-‏‪-‮⁦-⁩﻿]/g, '')
    .trim()
    .toLowerCase();
}

const rosterSet = new Set(ROSTER.map(normName));

const meta = $('Build post URLs').first().json.postMeta || [];
const reactions = $input.all().map(i => i.json);

const byPost = {};
for (const rx of reactions) {
  const key = rx.query && rx.query.post;
  if (!key) continue;
  if (!byPost[key]) byPost[key] = [];
  byPost[key].push(rx);
}

const postCount = meta.length;
let sumMembers = 0;
const out = [];

for (const m of meta) {
  const list = byPost[m.url] || [];
  const seen = new Set();
  for (const rx of list) {
    const actor = rx.actor || {};
    const nn = normName(actor.name);
    if (nn && rosterSet.has(nn)) seen.add(nn);
  }
  const members = seen.size;
  sumMembers += members;
  const rate_pct = Math.round(members / HEADCOUNT * 100);
  const date = (m.posted_at || '').slice(0, 10);
  const label = (m.text || '').slice(0, 40);
  out.push({ json: { date: date, label: label, members: members, headcount: HEADCOUNT, rate_pct: rate_pct, postCount: postCount } });
}

// The measured week is the COMPLETED Thursday-anchored week (the SOV default:
// week starts Thursday 00:00, ends Wednesday 23:59 — unless a metric
// explicitly specifies otherwise).
const thisThu = $now.startOf('day').minus({ days: ($now.weekday + 3) % 7 });
const wkStart = thisThu.minus({ weeks: 1 });   // the COMPLETED Thu-anchored week (Thu 00:00 ... Wed 23:59)
const wkEnd = wkStart.plus({ days: 6 });
const week_start = wkStart.toFormat('yyyy-MM-dd');
const weekly_avg_pct = postCount > 0 ? Math.round(sumMembers / (HEADCOUNT * postCount) * 100) : null;
for (const item of out) {
  item.json.weekly_avg_pct = weekly_avg_pct;
  item.json.week_start = week_start;
}

return out;

const rows = $input.all().map(i => i.json);
const postCount = $('Build post URLs').first().json.postCount;
// SOV default week: Thursday 00:00 -> Wednesday 23:59 (the completed one).
const thisThu = $now.startOf('day').minus({ days: ($now.weekday + 3) % 7 });
const wkStart = thisThu.minus({ weeks: 1 });   // the COMPLETED Thu-anchored week (Thu 00:00 ... Wed 23:59)
const wkEnd = wkStart.plus({ days: 6 });
const weekStartStr = wkStart.toFormat('MMM d');
const weekEndStr = wkEnd.toFormat('MMM d');
const headcount = rows.length ? rows[0].headcount : 38;
const weeklyAvg = rows.length ? rows[0].weekly_avg_pct : null;

let msg = '';
msg += '\ud83d\udcca LinkedIn employee engagement \u2014 week of ' + weekStartStr + '\u2013' + weekEndStr + ' (Thu\u2013Wed)\n';
msg += postCount + ' company posts.\n';
msg += '\n';
for (const r of rows) {
  msg += '\u2022 ' + r.date + ' (' + r.label + '): ' + r.members + '/' + headcount + ' = ' + r.rate_pct + '%\n';
}
msg += '\n';
msg += 'Weekly avg engagement per post: ' + weeklyAvg + '%\n';
msg += 'Members = name-match to the ' + headcount + '-person staff roster.\n';
msg += 'Source: SOV Supabase + live LinkedIn reactions.';
return [{ json: { slackText: msg, pct: weeklyAvg, headcount: headcount, post_count: postCount, week_start: wkStart.toFormat('yyyy-MM-dd') } }];

// SOV default week: Thursday 00:00 -> Wednesday 23:59 (the completed one).
const thisThu = $now.startOf('day').minus({ days: ($now.weekday + 3) % 7 });
const wkStart = thisThu.minus({ weeks: 1 });   // the COMPLETED Thu-anchored week (Thu 00:00 ... Wed 23:59)
const wkEnd = wkStart.plus({ days: 6 });
const range = wkStart.toFormat('MMM d') + '\u2013' + wkEnd.toFormat('MMM d');
let headcount = 38;
try { const cfg = $('Get roster config (Supabase)').first().json; const hc = Number(cfg && cfg.headcount); if (Number.isFinite(hc) && hc > 0) headcount = hc; } catch (e) { /* keep fallback */ }
const msg = '\ud83d\udcca LinkedIn employee engagement \u2014 week of ' + range + ' (Thu\u2013Wed): no company posts \u2014 N/A (week not counted toward averages).';
// pct NULL (not 0): no-post weeks are N/A and excluded from any average
// (SQL AVG skips nulls) and from week-over-week comparisons (Elan, 2026-08-03).
return [{ json: { slackText: msg, pct: null, headcount: headcount, post_count: 0, week_start: wkStart.toFormat('yyyy-MM-dd') } }];
